async function profileSourcePerformance(source,css){
  const target=normalizeUrl(source&&source.url);
  if(!target)return {ok:false,error:'Source invalide.'};
  const win=new BrowserWindow({
    show:false,width:412,height:915,useContentSize:true,frame:false,
    webPreferences:{contextIsolation:true,nodeIntegration:false,sandbox:true,webSecurity:false,allowRunningInsecureContent:true,backgroundThrottling:false}
  });
  let attached=false;
  const withTimeout=(promise,ms,label)=>new Promise((resolve,reject)=>{
    let settled=false;
    const timer=setTimeout(()=>{
      if(settled)return;
      settled=true;
      reject(new Error((label||'Opération')+' > '+ms+' ms.'));
    },ms);
    Promise.resolve(promise).then(value=>{
      if(settled)return;
      settled=true;clearTimeout(timer);resolve(value);
    },error=>{
      if(settled)return;
      settled=true;clearTimeout(timer);reject(error);
    });
  });
  try{
    try{
      win.webContents.debugger.attach('1.3');attached=true;
      await withTimeout(win.webContents.debugger.sendCommand('Performance.enable'),3000,'Performance.enable');
      await withTimeout(win.webContents.debugger.sendCommand('Network.enable'),3000,'Network.enable');
    }catch(_){
      try{if(attached&&win.webContents.debugger.isAttached())win.webContents.debugger.detach()}catch(_){}
      attached=false;
    }
    const started=Date.now();
    let mainLoadFailure=null;
    const domReady=new Promise((resolve,reject)=>{
      let settled=false;
      const finish=(error)=>{
        if(settled)return;
        settled=true;
        clearTimeout(timer);
        win.webContents.removeListener('dom-ready',onReady);
        win.webContents.removeListener('did-fail-load',onFail);
        if(error)reject(error);else resolve();
      };
      const onReady=()=>finish();
      const onFail=(_event,code,description,_url,isMainFrame)=>{
        if(isMainFrame===false)return;
        mainLoadFailure=new Error('Chargement échoué ('+code+') : '+description);
        finish(mainLoadFailure);
      };
      const timer=setTimeout(()=>finish(new Error('Chargement DOM > 15000 ms.')),15000);
      win.webContents.once('dom-ready',onReady);
      win.webContents.on('did-fail-load',onFail);
    });
    const navigation=win.loadURL(target).catch(error=>{mainLoadFailure=error;return null});
    await domReady;
    const loadMs=Date.now()-started;
    await new Promise(r=>setTimeout(r,450));
    try{win.webContents.stop()}catch(_){}
    navigation.catch(()=>{});
    if(css&&String(css).trim()&&String(css).trim()!=='/* Aucun ajustement. */'){
      try{await withTimeout(win.webContents.insertCSS(String(css),{cssOrigin:'author'}),3000,'insertCSS')}catch(_){}
      await new Promise(r=>setTimeout(r,160));
    }
    let metricMap={};
    if(attached){
      try{
        const rawMetrics=await withTimeout(win.webContents.debugger.sendCommand('Performance.getMetrics'),3000,'Performance.getMetrics');
        (rawMetrics.metrics||[]).forEach(item=>{metricMap[item.name]=item.value});
      }catch(_){}
    }
    let page={url:target,nodes:0,images:0,brokenImages:0,estimatedDecodedImageBytes:0,resources:0,transferBytes:0,encodedBytes:0,decodedBytes:0,resourceTypes:{},navigation:null,paints:[]};
    try{page=await withTimeout(win.webContents.executeJavaScript("(function(){var resources=performance.getEntriesByType('resource')||[];var nav=(performance.getEntriesByType('navigation')||[])[0]||null;var paints=performance.getEntriesByType('paint')||[];var images=Array.from(document.images||[]);var imageNaturalBytes=0,brokenImages=0;images.forEach(function(img){if(!img.complete||!img.naturalWidth)brokenImages++;imageNaturalBytes+=Math.max(0,(img.naturalWidth||0)*(img.naturalHeight||0)*4);});var transfer=resources.reduce(function(n,r){return n+(Number(r.transferSize)||0)},0);var encoded=resources.reduce(function(n,r){return n+(Number(r.encodedBodySize)||0)},0);var decoded=resources.reduce(function(n,r){return n+(Number(r.decodedBodySize)||0)},0);var byType={};resources.forEach(function(r){var k=r.initiatorType||'other';if(!byType[k])byType[k]={count:0,transfer:0,duration:0};byType[k].count++;byType[k].transfer+=Number(r.transferSize)||0;byType[k].duration+=Number(r.duration)||0;});return {url:location.href,nodes:document.getElementsByTagName('*').length,images:images.length,brokenImages:brokenImages,estimatedDecodedImageBytes:imageNaturalBytes,resources:resources.length,transferBytes:transfer,encodedBytes:encoded,decodedBytes:decoded,resourceTypes:byType,navigation:nav?{domContentLoaded:nav.domContentLoadedEventEnd,loadEventEnd:nav.loadEventEnd,responseStart:nav.responseStart,responseEnd:nav.responseEnd,duration:nav.duration}:null,paints:paints.map(function(x){return {name:x.name,startTime:x.startTime}})};})()",true),5000,'performance page metrics')}catch(error){page.profileError=String(error&&error.message||error)}
    let processMemory=null;
    try{processMemory=await withTimeout(win.webContents.getProcessMemoryInfo(),3000,'process memory')}catch(_){}
    const secToMs=name=>Math.round((Number(metricMap[name])||0)*10000)/10;
    const bytes=name=>Math.round(Number(metricMap[name])||0);
    const metrics={
      loadMs,
      taskDurationMs:secToMs('TaskDuration'),
      scriptDurationMs:secToMs('ScriptDuration'),
      layoutDurationMs:secToMs('LayoutDuration'),
      recalcStyleDurationMs:secToMs('RecalcStyleDuration'),
      layoutCount:Math.round(Number(metricMap.LayoutCount)||0),
      recalcStyleCount:Math.round(Number(metricMap.RecalcStyleCount)||0),
      domNodes:Math.round(Number(metricMap.Nodes)||Number(page.nodes)||0),
      documents:Math.round(Number(metricMap.Documents)||1),
      jsHeapUsedBytes:bytes('JSHeapUsedSize'),
      jsHeapTotalBytes:bytes('JSHeapTotalSize')
    };
    const findings=[];
    if(metrics.domNodes>1500)findings.push({type:'large-dom',value:metrics.domNodes,message:'DOM volumineux : '+metrics.domNodes+' nœuds.'});
    if(metrics.taskDurationMs>2000)findings.push({type:'task-duration',value:metrics.taskDurationMs,message:'Temps cumulé de tâches Chromium élevé : '+metrics.taskDurationMs+' ms.'});
    if(metrics.scriptDurationMs>1200)findings.push({type:'script-duration',value:metrics.scriptDurationMs,message:'Temps JavaScript cumulé élevé : '+metrics.scriptDurationMs+' ms.'});
    if(metrics.layoutCount>100)findings.push({type:'layout-count',value:metrics.layoutCount,message:'Nombre de layouts élevé : '+metrics.layoutCount+'.'});
    if(metrics.recalcStyleCount>150)findings.push({type:'style-recalc',value:metrics.recalcStyleCount,message:'Nombre de recalculs de style élevé : '+metrics.recalcStyleCount+'.'});
    if(metrics.jsHeapUsedBytes>100*1024*1024)findings.push({type:'heap',value:metrics.jsHeapUsedBytes,message:'Heap JavaScript utilisé > 100 Mo.'});
    if(Number(page.transferBytes)>5*1024*1024)findings.push({type:'transfer',value:page.transferBytes,message:'Plus de 5 Mo transférés pour ce chargement.'});
    if(Number(page.estimatedDecodedImageBytes)>80*1024*1024)findings.push({type:'images-memory',value:page.estimatedDecodedImageBytes,message:'Images potentiellement lourdes une fois décodées en mémoire.'});
    if(Number(page.brokenImages)>0)findings.push({type:'broken-images',value:page.brokenImages,message:page.brokenImages+' image(s) non chargée(s).'});
    return {ok:true,metrics,page,processMemory,findings};
  }catch(error){
    return {ok:false,error:'Profilage impossible : '+String(error&&error.message||error)};
  }finally{
    try{if(attached&&win.webContents.debugger.isAttached())win.webContents.debugger.detach()}catch(_){}
    if(!win.isDestroyed())win.destroy();
  }
}

