'use strict';
(()=>{
function geometry(width,height,cssWidth,top,bottomStart){if(![width,height,cssWidth,top,bottomStart].every(Number.isFinite)||width<=0||height<=0||cssWidth<240||top<0||bottomStart<=top||bottomStart>height)throw Error('Mesures invalides : la limite basse doit rester sous la limite haute.');const scale=cssWidth/width;return {width:Math.round(cssWidth),height:Math.round(height*scale),topInset:Math.round(top*scale),bottomInset:Math.round((height-bottomStart)*scale)}}
window.AndroidScreenCalibration={geometry,open(dataUrl,apply,cssWidth=412){const dialog=document.createElement('dialog');dialog.style.cssText='max-width:900px;width:90vw;border:1px solid #cab5ef;border-radius:20px;padding:20px;background:#fff;color:#211832';dialog.innerHTML='<h2>Dimensions de votre écran Android</h2><p>Utilisez une capture complète du téléphone, sans recadrage. Déplacez les deux lignes sur le bord inférieur de la barre du haut et le bord supérieur de la barre du bas.</p><div style="display:flex;gap:24px;flex-wrap:wrap"><div id="ascImageBox" style="position:relative;touch-action:none"><img id="ascImage" style="display:block;max-height:52vh;max-width:55vw"><div id="ascTopLine" style="position:absolute;left:0;right:0;border-top:3px solid #f04065;cursor:ns-resize;z-index:2"><span style="background:#f04065;color:white;font-size:12px">Limite haute</span></div><div id="ascBottomLine" style="position:absolute;left:0;right:0;border-top:3px solid #0086a8;cursor:ns-resize;z-index:2"><span style="background:#0086a8;color:white;font-size:12px">Limite basse</span></div></div><div><label>Largeur de l’écran en px CSS<br><input id="ascWidth" type="number" min="240"></label><p>Ce sont les pixels CSS, pas la résolution physique.<br>Utilisez « Mesurer l’écran Android connecté » pour les récupérer.</p><label>Fin de la barre du haut · pixels de la capture<br><input id="ascTop" type="number" min="0"></label><br><label>Début de la barre du bas · pixels de la capture<br><input id="ascBottom" type="number" min="0"></label><p id="ascResult" aria-live="polite"></p><button id="ascApply">Appliquer à l’éditeur</button> <button id="ascCancel">Annuler</button></div></div>';document.body.append(dialog);const $=id=>dialog.querySelector('#'+id),image=$('ascImage');$('ascWidth').value=cssWidth;const refresh=()=>{if(!image.naturalWidth)return;const top=Number($('ascTop').value),bottom=Number($('ascBottom').value);$('ascTopLine').style.top=top/image.naturalHeight*100+'%';$('ascBottomLine').style.top=bottom/image.naturalHeight*100+'%';try{const p=geometry(image.naturalWidth,image.naturalHeight,Number($('ascWidth').value),top,bottom);$('ascResult').textContent=p.width+' × '+p.height+' px CSS · haut '+p.topInset+' · bas '+p.bottomInset;$('ascApply').disabled=false}catch(e){$('ascResult').textContent=e.message;$('ascApply').disabled=true}};image.onload=()=>{$('ascTop').value=Math.round(image.naturalHeight*.035);$('ascBottom').value=Math.round(image.naturalHeight*.94);refresh()};for(const id of ['ascWidth','ascTop','ascBottom'])$(id).oninput=refresh;for(const [line,input] of [['ascTopLine','ascTop'],['ascBottomLine','ascBottom']]){$(line).onpointerdown=e=>{e.preventDefault();$(line).setPointerCapture(e.pointerId)};$(line).onpointermove=e=>{if(!$(line).hasPointerCapture(e.pointerId))return;const r=image.getBoundingClientRect();$(input).value=Math.round(Math.max(0,Math.min(image.naturalHeight,(e.clientY-r.top)/r.height*image.naturalHeight)));refresh()}}const close=()=>{dialog.close();dialog.remove()};$('ascCancel').onclick=close;dialog.addEventListener('cancel',close);$('ascApply').onclick=()=>{const p=geometry(image.naturalWidth,image.naturalHeight,Number($('ascWidth').value),Number($('ascTop').value),Number($('ascBottom').value));apply(p);close()};image.src=dataUrl;dialog.showModal()}};
})();

