async function choose(){if(dirty)await save();selected=files.find(f=>f.name===$('apkFileList').value);$('apkFileName').textContent=selected?.name||'';$('apkText').disabled=!selected?.text;$('apkSave').disabled=!selected?.text;$('apkReplaceImage').disabled=!selected?.image;$('apkText').value='';if(selected?.text){const r=await command('read',{name:selected.name});$('apkText').value=r.content;contentHash=r.hash;dirty=false}}
