(()=>{'use strict';const api=window.StudioSyncApi;if(!api)return;let state;const button=document.createElement('button');button.textContent='Synchronisation';button.title='Recevoir et publier les fichiers de Studio dans la branche partagée GitHub';button.style.cssText='position:fixed;bottom:12px;left:12px;z-index:1000;background:#eee9ff;color:#302455;border:1px solid #b9a7e3;border-radius:10px;padding:9px 14px';document.body.append(button);
const dialog=document.createElement('dialog');dialog.style.cssText='max-width:610px;width:90%;border:1px solid #b9a7e3;border-radius:16px;padding:24px;color:#302455;background:#faf8ff';dialog.innerHTML='<h2>Studio partagé</h2><p>Les fichiers du logiciel sont partagés avec l’assistant dans <b>Wokgui/Radio-intelligente</b>, branche <b>feature/interface-studio-live</b>.</p><p>Ce dépôt est public. Seuls les fichiers du logiciel sont synchronisés : les projets, captures, APK et données du téléphone restent sur ton PC.</p><p data-status role="status"></p><label><input type="checkbox" data-enabled> Recevoir les mises à jour automatiquement</label><br><label><input type="checkbox" data-auto> Publier mes modifications automatiquement</label><p><button data-pull>Actualiser</button> <button data-publish>Publier maintenant</button></p><fieldset><legend>Autoriser la publication depuis ce PC</legend><p>Crée un jeton GitHub limité à ce dépôt, avec l’autorisation <b>Contents : Read and write</b>, puis colle-le ici. Il est protégé par Windows et conservé uniquement sur ce PC.</p><input type="password" data-token autocomplete="off" placeholder="Jeton GitHub" style="width:95%"><p><button data-connect>Connecter GitHub</button> <button data-disconnect>Déconnecter</button></p></fieldset><section data-conflicts hidden><h3>Modifications concurrentes</h3><pre style="white-space:pre-wrap" data-files></pre><p>Une sauvegarde précède tout remplacement. Choisis la version à conserver pour les fichiers en conflit.</p><button data-local>Garder ma version</button> <button data-remote>Prendre la version partagée</button></section><p data-restart hidden>Des fichiers internes ont changé. Enregistre ton projet, puis <button data-relaunch>relance Studio</button>.</p><p><button data-diagnostic>Exporter le diagnostic</button> <button data-close>Fermer</button></p>';document.body.append(dialog);const $=n=>dialog.querySelector('[data-'+n+']');
function render(s){if(!s.ok){$('status').textContent=s.message;return;}state=s;$('status').textContent=s.message;$('enabled').checked=s.enabled;$('auto').checked=s.autoPublish;$('auto').disabled=!s.connected;$('publish').disabled=!s.connected||s.busy;$('conflicts').hidden=!s.conflicts?.length;$('files').textContent=(s.conflicts||[]).join('\n');$('restart').hidden=!s.restartRequired;button.textContent=s.conflicts?.length?'Synchronisation : conflit':s.restartRequired?'Synchronisation : relancer':'Synchronisation';}
async function send(action,p={}){try{render(await api.command({action,...p}));}catch(e){$('status').textContent=e.message;}}
button.onclick=()=>{dialog.showModal();send('status');};$('close').onclick=()=>dialog.close();for(const n of ['pull','publish','disconnect','diagnostic'])$(n).onclick=()=>send(n);$('connect').onclick=()=>{const token=$('token').value;$('token').value='';send('connect',{token});};for(const n of ['local','remote'])$(n).onclick=()=>send('resolve',{choice:n});for(const n of ['enabled','auto'])$(n).onchange=()=>send('settings',{enabled:$('enabled').checked,autoPublish:$('auto').checked});$('relaunch').onclick=()=>{if(confirm('Ton projet est-il enregistré ? Studio va se relancer.'))send('restart');};api.onStatus(render);send('status');})();

webapp/studio-workspace.css.text:
:root{--studio-accent:#7548e8;--studio-line:#e7dff0;--studio-ink:#302340;--studio-muted:#796e89}
body.studio-unified{height:100vh;display:flex;flex-direction:column;overflow:hidden}
.studio-unified>header{flex:none;min-height:72px;flex-wrap:wrap;padding:10px 16px;gap:10px}
.studio-unified .brand{min-width:240px}.studio-unified .brand small{max-width:250px}
.studio-unified #modeSwitch{display:none}.studio-unified .top-actions{gap:6px}
.studio-unified>main{flex:1;min-height:0;height:auto;grid-template-columns:minmax(0,1fr) 360px;padding:12px;gap:12px}
.studio-workspace-bar{flex:none;display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:10px 16px;background:#fff;border-bottom:1px solid var(--studio-line)}
.studio-tabs{display:flex;gap:4px;padding:4px;background:#f5f0fb;border:1px solid var(--studio-line);border-radius:13px}
.studio-tabs button{border:0;border-radius:9px;background:transparent;padding:9px 14px;color:var(--studio-muted);font:700 13px system-ui}
.studio-tabs button[aria-selected="true"]{background:#fff;color:#6332bc;box-shadow:0 2px 8px #4a286315}
.studio-workspace-note{font-size:12px;color:var(--studio-muted);flex:1;min-width:190px}
.studio-bars-control{font-size:12px;color:var(--studio-muted)}.studio-bars-control select{padding:7px;border:1px solid var(--studio-line);border-radius:8px;background:white;color:var(--studio-ink)}
.studio-runtime-pane{min-width:0;min-height:0;height:100%;position:relative;background:#faf7fe;border:1px solid var(--studio-line);border-radius:18px;overflow:hidden}
.studio-runtime-pane[hidden]{display:none!important}.studio-runtime-caption{font-size:12px;padding:12px;color:var(--studio-muted)}
.studio-runtime-mount{position:absolute;inset:0}.studio-unified[data-workspace="run"]>main{grid-template-columns:minmax(0,1fr)}
.studio-unified[data-workspace="run"] .workspace,.studio-unified[data-workspace="run"] .side{display:none!important}
.studio-unified[data-workspace="compare"]>main{grid-template-columns:minmax(280px,1fr) minmax(360px,1fr) 320px}
.studio-unified[data-workspace="compare"] .workspace{padding:8px}
.studio-unified .side{display:flex!important;flex-direction:column;gap:10px;min-width:0;height:100%;overflow:auto;padding:0 2px 12px}
.studio-category-nav{order:-2;flex:none;display:flex;flex-wrap:wrap;gap:6px;padding:10px;border:1px solid var(--studio-line);border-radius:14px;background:#fff}
.studio-category-nav button{font:700 11px system-ui;border:1px solid var(--studio-line);border-radius:8px;padding:7px 9px;background:#faf8fe;color:var(--studio-muted)}
.studio-category-nav button[aria-pressed="true"]{color:#6535b5;border-color:#bda6e5;background:#f0e7ff}
.studio-category-title{flex:none;margin:8px 2px 0;font-size:15px;color:var(--studio-ink)}.studio-category-title small{display:block;margin-top:4px;color:var(--studio-muted);font-size:11px;font-weight:500}
.studio-unified .side>.card{flex:none;width:100%}.studio-unified .side>.card[hidden],.studio-category-title[hidden]{display:none!important}
.studio-info{margin-left:6px;width:23px;height:23px;border:1px solid #d5c7e8;border-radius:50%;font:700 12px system-ui;background:#f7f1ff;color:#7549ac;flex:none}
.studio-help-text{font-size:12px!important;background:#f4eefb;padding:9px;border-radius:8px;margin:0 8px 8px!important;color:#69547f!important}.studio-help-text[hidden]{display:none}
.studio-actions-group{position:relative}.studio-actions-group summary{list-style:none}.studio-actions-group[open]>div{position:absolute;right:0;top:calc(100% + 8px);min-width:230px;z-index:3000;display:grid;gap:6px;padding:10px;background:#fff;border:1px solid var(--studio-line);border-radius:14px;box-shadow:0 12px 35px #39215126}
.studio-tutorial{width:min(780px,90vw);max-height:85vh;overflow:auto;border:1px solid #d2c0e5;border-radius:20px;padding:26px;background:#fff;color:var(--studio-ink);font:15px/1.6 system-ui}
.studio-tutorial::backdrop{background:#23172d99;backdrop-filter:blur(4px)}.studio-tutorial h2{font-size:24px;margin:0 0 6px}.studio-tutorial nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.studio-tutorial button{padding:10px 15px;border:1px solid var(--studio-line);border-radius:10px;background:#f5eefe;color:#6532ad;font:700 13px system-ui}.studio-tutorial-step{font-size:12px;color:var(--studio-muted)}
/* The real Android page shares the Studio palette and controls. */
body:has(#viewer){background:#f6f2fb;color:var(--studio-ink);height:100vh;display:flex;flex-direction:column;overflow:hidden;font:14px system-ui}
body:has(#viewer) header{padding:12px 16px;background:#fff;border-bottom:1px solid var(--studio-line);flex:none}
body:has(#viewer) main{flex:1;min-height:0;height:auto;display:grid;grid-template-columns:minmax(240px,300px) minmax(0,1fr);gap:12px;padding:12px}
body:has(#viewer) section{background:#fff;border:1px solid var(--studio-line);border-radius:14px;padding:12px;min-height:0}
body:has(#viewer) button,body:has(#viewer) select,body:has(#viewer) input{background:#faf7ff;color:var(--studio-ink);border:1px solid #dfd2ed;border-radius:9px;padding:8px;font-size:12px}
body:has(#viewer) button:hover{background:#ede3fc}body:has(#viewer) small{color:var(--studio-muted)}body:has(#viewer) a{color:#7941c4}
body:has(#viewer) h2{font-size:16px;color:#64389c}body:has(#viewer) #screen{height:auto;flex:1;min-height:180px;border-radius:12px;background:#16111f}
body:has(#viewer) #result{max-height:100px;font-size:11px}body:has(#viewer) #streamState{font-size:11px;color:var(--studio-muted)}
@media(max-width:1200px){.studio-unified[data-workspace="compare"]>main{grid-template-columns:minmax(250px,1fr) minmax(300px,1fr)}.studio-unified[data-workspace="compare"] .side{display:none!important}}
@media(max-width:750px){.studio-unified>main{grid-template-columns:minmax(0,1fr) 300px}.studio-workspace-note{width:100%}.studio-tabs button{padding:8px}.studio-unified[data-workspace="compare"]>main{grid-template-columns:1fr;overflow:auto}.studio-unified[data-workspace="compare"] .workspace,.studio-unified[data-workspace="compare"] .studio-runtime-pane{min-height:540px}body:has(#viewer) main{grid-template-columns:1fr;overflow:auto}body:has(#viewer) #viewer{min-height:480px}}

body.embedded-runtime main{grid-template-columns:1fr;overflow:hidden}body.embedded-runtime .android-settings{display:none}body.embedded-runtime.show-android-settings main{grid-template-columns:minmax(220px,300px) minmax(0,1fr)}body.embedded-runtime.show-android-settings .android-settings{display:block}@media(max-width:700px){body.embedded-runtime.show-android-settings main{grid-template-columns:1fr;overflow:auto}body.embedded-runtime.show-android-settings #viewer{display:none}}

.studio-info::before{content:"?"}

