webapp/visual-editor.css.text:
/* Editeur visuel optionnel : aucun style de l'application n'est modifie hors mode actif. */
.ve-launcher {
  width: 100%;
  min-height: 48px;
  margin-top: 12px;
  border: 1px solid #d7c5ea;
  border-radius: 15px;
  background: #f3eafa;
  color: #5e2ca7;
  font-weight: 900;
}

.ve-toolbar,
.ve-selection {
  display: none;
}

body.ve-active {
  cursor: crosshair !important;
  touch-action: none;
}
body.ve-active.ve-space-pan{cursor:grab!important}
body.ve-active.ve-canvas-panning{cursor:grabbing!important}


body.ve-active .ve-toolbar {
  position: fixed;
  z-index: 2147483647;
  left: max(8px, env(safe-area-inset-left));
  right: max(8px, env(safe-area-inset-right));
  bottom: max(8px, env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 8px;
  padding: 10px;
  border: 1px solid #ffffff4d;
  border-radius: 16px;
  background: #21182ff2;
  color: #fff;
  box-shadow: 0 12px 35px #0007;
  font: 700 12px/1.25 system-ui, -apple-system, "Segoe UI", sans-serif;
  cursor: default !important;
  touch-action: auto;
}

.ve-toolbar * {
  box-sizing: border-box;
}

.ve-info {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.ve-target {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #e4cfff;
}

.ve-metrics {
  font-variant-numeric: tabular-nums;
}

.ve-help {
  color: #c8bfd0;
  font-size: 10px;
}

.ve-actions {
  display: grid;
  grid-template-columns: repeat(2, auto);
  gap: 6px;
}

.ve-actions button {
  min-width: 42px;
  min-height: 34px;
  padding: 5px 9px;
  border: 0;
  border-radius: 9px;
  background: #fff;
  color: #4f287d;
  font: 800 11px/1 system-ui, -apple-system, "Segoe UI", sans-serif;
}

.ve-actions .ve-close {
  background: #ee557c;
  color: #fff;
}

body.ve-active .ve-selection {
  position: fixed;
  z-index: 2147483646;
  display: block;
  border: 2px solid #b14cff;
  background: #b14cff12;
  box-shadow: 0 0 0 1px #fff9, 0 0 0 100vmax #0000000a;
  pointer-events: none;
}

body.ve-active .ve-toolbar,
body.ve-active .ve-toolbar * {
  cursor: default !important;
}

@media (min-width: 700px) {
  body.ve-active .ve-toolbar {
    left: 50%;
    right: auto;
    width: min(680px, calc(100% - 20px));
    transform: translateX(-50%);
  }
}


body.ve-hosted .ve-launcher,
body.ve-hosted .ve-toolbar {
  display: none !important;
}

body.ve-hosted.ve-active {
  cursor: crosshair !important;
}

body.ve-hosted.ve-active .ve-selection {
  border-color: #7c3aed;
  background:
    linear-gradient(90deg, transparent calc(50% - .5px), #7c3aed66 calc(50% - .5px), #7c3aed66 calc(50% + .5px), transparent calc(50% + .5px)),
    linear-gradient(transparent calc(50% - .5px), #7c3aed66 calc(50% - .5px), #7c3aed66 calc(50% + .5px), transparent calc(50% + .5px)),
    #b14cff10;
}


/* Poignées de redimensionnement et guides d’alignement façon éditeur de mise en page. */
body.ve-active .ve-selection{
  overflow:visible!important;
}
.ve-handle{
  position:absolute;
  width:12px;
  height:12px;
  border:2px solid #7c3aed;
  border-radius:50%;
  background:#fff;
  box-shadow:0 1px 4px #0004;
  pointer-events:auto;
  touch-action:none;
}
.ve-handle-nw{left:-7px;top:-7px;cursor:nwse-resize}
.ve-handle-ne{right:-7px;top:-7px;cursor:nesw-resize}
.ve-handle-sw{left:-7px;bottom:-7px;cursor:nesw-resize}
.ve-handle-se{right:-7px;bottom:-7px;cursor:nwse-resize}
.ve-handle-n,.ve-handle-s{width:24px;height:8px;border-radius:999px}
.ve-handle-w,.ve-handle-e{width:8px;height:24px;border-radius:999px}
.ve-handle-n{top:-5px;left:75%;transform:translateX(-50%);cursor:ns-resize}
.ve-handle-s{bottom:-5px;left:75%;transform:translateX(-50%);cursor:ns-resize}
.ve-handle-w{left:-5px;top:75%;transform:translateY(-50%);cursor:ew-resize}
.ve-handle-e{right:-5px;top:75%;transform:translateY(-50%);cursor:ew-resize}
.ve-media-focal{
  position:absolute;z-index:8;display:none;align-items:center;justify-content:center;
  width:26px;height:26px;padding:0;border:2px solid #fff;border-radius:50%;
  background:#7c3aed;color:#fff;font:900 16px/1 system-ui,-apple-system,"Segoe UI",sans-serif;
  box-shadow:0 0 0 2px #7c3aed,0 3px 10px #0005;
  transform:translate(-50%,-50%);pointer-events:auto;touch-action:none;cursor:move!important
}
.ve-media-focal:active{transform:translate(-50%,-50%) scale(.94)}
body.ve-media-drop-ready{cursor:copy!important}
body.ve-media-drop-ready .ve-selection{box-shadow:0 0 0 2px #22c55e,0 0 0 100vmax #16a34a10!important}

.ve-anchor-pin{
  position:absolute;z-index:4;display:none;align-items:center;justify-content:center;
  width:22px;height:22px;padding:0;border:1px solid #7c3aed;border-radius:7px;
  background:#fff;color:#6f49f5;font:900 12px/1 system-ui,-apple-system,"Segoe UI",sans-serif;
  box-shadow:0 2px 8px #0003;pointer-events:auto;touch-action:manipulation;cursor:pointer!important
}
.ve-anchor-pin:hover,.ve-anchor-pin.active{background:#6f49f5;color:#fff}
.ve-anchor-left{left:-29px;top:50%;transform:translateY(-50%)}
.ve-anchor-right{right:-29px;top:50%;transform:translateY(-50%)}
.ve-anchor-top{top:-29px;left:50%;transform:translateX(-50%)}
.ve-anchor-bottom{bottom:-29px;left:50%;transform:translateX(-50%)}
.ve-anchor-hcenter{top:-29px;left:25%;transform:translateX(-50%)}
.ve-anchor-vcenter{left:-29px;top:25%;transform:translateY(-50%)}
.ve-anchor-hstretch{bottom:-29px;left:38%;transform:translateX(-50%)}
.ve-anchor-vstretch{bottom:-29px;left:62%;transform:translateX(-50%)}
body.ve-active .ve-selection.ve-single-selection .ve-anchor-pin{display:flex}
.ve-selection-secondary .ve-anchor-pin{display:none!important}
.ve-box-handle{
  position:absolute;z-index:5;display:none;align-items:center;justify-content:center;
  min-width:24px;min-height:18px;padding:2px 5px;border:1px solid currentColor;border-radius:6px;
  background:#fff;font:850 9px/1 system-ui,-apple-system,"Segoe UI",sans-serif;
  box-shadow:0 2px 8px #0003;pointer-events:auto;touch-action:none;user-select:none
}
.ve-box-handle.margin{color:#e67e22}
.ve-box-handle.padding{color:#16a085}
.ve-box-handle[data-side="top"],.ve-box-handle[data-side="bottom"]{cursor:ns-resize}
.ve-box-handle[data-side="left"],.ve-box-handle[data-side="right"]{cursor:ew-resize}
.ve-box-handle.margin[data-side="top"]{top:-54px;left:50%;transform:translateX(-50%)}
.ve-box-handle.margin[data-side="bottom"]{bottom:-54px;left:50%;transform:translateX(-50%)}
.ve-box-handle.margin[data-side="left"]{left:-54px;top:50%;transform:translateY(-50%)}
.ve-box-handle.margin[data-side="right"]{right:-54px;top:50%;transform:translateY(-50%)}
.ve-box-handle.padding[data-side="top"]{top:7px;left:50%;transform:translateX(-50%)}
.ve-box-handle.padding[data-side="bottom"]{bottom:7px;left:50%;transform:translateX(-50%)}
.ve-box-handle.padding[data-side="left"]{left:7px;top:50%;transform:translateY(-50%)}
.ve-box-handle.padding[data-side="right"]{right:7px;top:50%;transform:translateY(-50%)}
body.ve-active .ve-selection.ve-single-selection.ve-box-model-visible .ve-box-handle{display:flex}
.ve-box-ring-margin,.ve-box-ring-padding{
  position:fixed;z-index:2147483643;display:none;pointer-events:none;border-style:solid;box-sizing:border-box
}
