  }

  function compareNumeric(actual,operator,expected){
    if(operator==='>')return actual>expected;
    if(operator==='>=')return actual>=expected;
    if(operator==='<')return actual<expected;
    if(operator==='<=')return actual<=expected;
    if(operator==='='||operator==='==')return Math.abs(actual-expected)<.75;
    return null;
  }

  function evaluateContainerAtom(atom,containerEl,rect){
