  function deleteSelected() {
    if (!active || !selected) return;
    selectionElements().forEach(function (element) {
      const state = remember(element);
      if (!state || state.locked) return;
      state.deleted = true;
      applyState(element, state, false);
    });
    selected = null;
    selectedSet.clear();
    if(isolationActive){
      isolationActive=false;
